function [is, k, knowledge, los] = kpi_ecss_kind(kind)
%KPI_ECSS_KIND  Which ECSS index a kind is (is false for any other kind): the relative, mean or drift index, of the knowledge error
%   (rke, mke, kde) or the performance error, across the boresight (_los) or three-axis.
%   kind: MetricKind (passed a choice, as its option's number)
%   returns is: bool (passed true or false)
%   returns k: EcssIndex (passed a choice, as its option's number)
%   returns knowledge: bool (passed true or false)
%   returns los: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    is = false;
    k = 0;
    knowledge = false;
    los = false;
    is = true;
    k = 0;
    knowledge = false;
    los = false;
    if ((((kind == 16) || (kind == 17)) || (kind == 22)) || (kind == 23))
        k = 0;
    elseif ((((kind == 18) || (kind == 19)) || (kind == 24)) || (kind == 25))
        k = 1;
    elseif ((((kind == 20) || (kind == 21)) || (kind == 26)) || (kind == 27))
        k = 2;
    else
        is = false;
    end
    knowledge = ((((((kind == 22) || (kind == 23)) || (kind == 24)) || (kind == 25)) || (kind == 26)) || (kind == 27));
    los = ((((((kind == 17) || (kind == 19)) || (kind == 21)) || (kind == 23)) || (kind == 25)) || (kind == 27));
end
